import{_ as t,o as h,c as i,a2 as g}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Luật Lao động Cộng sinh","description":"","frontmatter":{},"headers":[],"relativePath":"vi/41-共生劳动法.md","filePath":"vi/41-共生劳动法.md","lastUpdated":null}'),a={name:"vi/41-共生劳动法.md"};function c(o,n,l,u,p,r){return h(),i("div",null,[...n[0]||(n[0]=[g('<h1 id="luat-lao-đong-cong-sinh" tabindex="-1">Luật Lao động Cộng sinh <a class="header-anchor" href="#luat-lao-đong-cong-sinh" aria-label="Permalink to &quot;Luật Lao động Cộng sinh&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Dự án</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>41</td></tr><tr><td>Mô-đun</td><td>Hệ thống pháp luật và khuôn khổ quản trị</td></tr><tr><td>Từ khóa cốt lõi</td><td>Lao động cộng sinh, nhiều lao động nhiều thu nhập, quyền lao động, hợp đồng sản xuất liên hợp, phản đối bóc lột</td></tr></tbody></table><h2 id="_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" tabindex="-1">1. Mục đích lập pháp và nguyên tắc cơ bản <a class="header-anchor" href="#_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" aria-label="Permalink to &quot;1. Mục đích lập pháp và nguyên tắc cơ bản&quot;">​</a></h2><p>《Luật Lao động Cộng sinh》 là một trong những luật pháp cốt lõi trong hệ thống pháp luật của văn minh cộng sinh neo, song song với 《Hiến pháp Cộng sinh》, nhằm quy phạm hóa tất cả các hành vi lao động và đóng góp bên trong Hengyuanzhou, thiết lập trật tự phân phối &quot;nhiều lao động nhiều thu nhập, tự sinh tự trưởng&quot;, và từ cấp độ pháp luật nhổ bỏ gốc rễ của bóc lột kiểu cướp đoạt.</p><p>Luật này thiết lập các nguyên tắc cơ bản sau:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Nguyên tắc phẩm giá lao động</td><td>Mọi lao động hợp pháp đều được pháp luật bảo vệ, phẩm giá nhân cách của người lao động không bị xâm phạm</td></tr><tr><td>Nguyên tắc nhiều lao động nhiều thu nhập</td><td>Thù lao lao động gắn trực tiếp với lượng đóng góp, đóng góp càng lớn thu nhập càng cao, cấm hưởng thụ không lao động</td></tr><tr><td>Nguyên tắc lao động tự nguyện</td><td>Cấm lao động cưỡng bức và nô lệ, người lao động có quyền tự do lựa chọn nội dung và phương thức lao động</td></tr><tr><td>Nguyên tắc thù lao công bằng</td><td>Đồng công đồng thù lao, cấm phân biệt đối xử thù lao dựa trên tộc, trình độ tu luyện, xuất thân</td></tr><tr><td>Nguyên tắc đảm bảo lao động</td><td>Nhà nước và văn minh có nghĩa vụ cung cấp cho người lao động môi trường lao động an toàn và an sinh xã hội cơ bản</td></tr><tr><td>Nguyên tắc hợp tác cộng sinh</td><td>Khuyến khích hợp tác và tương trợ giữa người lao động, phản đối cạnh tranh ác tính và trò chơi không hòa vốn</td></tr></tbody></table><h2 id="_2-quyen-co-ban-cua-nguoi-lao-đong" tabindex="-1">2. Quyền cơ bản của người lao động <a class="header-anchor" href="#_2-quyen-co-ban-cua-nguoi-lao-đong" aria-label="Permalink to &quot;2. Quyền cơ bản của người lao động&quot;">​</a></h2><p>Luật Lao động Cộng sinh trao cho mọi sự sống có khả năng lao động bên trong Hengyuanzhou các quyền sau:</p><ol><li><strong>Quyền việc làm bình đẳng</strong>: Không có sự sống nào bị phân biệt đối xử vì tộc, trình độ tu luyện, xuất thân, giới tính, v.v. trong quá trình tìm việc và được tuyển dụng.</li><li><strong>Quyền tự do lựa chọn nghề nghiệp</strong>: Người lao động có quyền lựa chọn nghề nghiệp, vị trí công việc và địa điểm làm việc theo ý chí và năng lực của mình, và có quyền thay đổi nghề nghiệp theo pháp luật.</li><li><strong>Quyền thù lao hợp lý</strong>: Người lao động có quyền nhận thù lao phù hợp với đóng góp lao động của mình, thù lao không được thấp hơn tiêu chuẩn đảm bảo tối thiểu do văn minh quy định.</li><li><strong>Quyền nghỉ ngơi và nghỉ phép</strong>: Người lao động có quyền nhận sự sắp xếp thời gian làm việc hợp lý và nghỉ phép định kỳ, cấm kéo dài thời gian lao động vô hạn.</li><li><strong>Quyền an toàn lao động</strong>: Người lao động có quyền làm việc trong môi trường an toàn, vệ sinh, người sử dụng lao động phải cung cấp điều kiện bảo vệ lao động đạt tiêu chuẩn.</li><li><strong>Quyền đào tạo nghề</strong>: Người lao động có quyền nhận đào tạo kỹ năng nghề nghiệp và hướng dẫn tu luyện, người sử dụng lao động và nhà nước có nghĩa vụ cung cấp nguồn lực đào tạo.</li><li><strong>Quyền lập hội và đàm phán</strong>: Người lao động có quyền thành lập hoặc tham gia hội người lao động theo pháp luật, và có quyền bảo vệ quyền lợi của mình thông qua đàm phán tập thể.</li><li><strong>Quyền khiếu nại và cứu trợ</strong>: Người lao động khi quyền lợi lao động bị xâm phạm có quyền khiếu nại và khởi kiện trước cơ quan trọng tài lao động và Tòa án Cộng sinh.</li></ol><h2 id="_3-hop-phap-hoa-co-che-hop-đong-san-xuat-lien-hop" tabindex="-1">3. Hợp pháp hóa cơ chế hợp đồng sản xuất liên hợp <a class="header-anchor" href="#_3-hop-phap-hoa-co-che-hop-đong-san-xuat-lien-hop" aria-label="Permalink to &quot;3. Hợp pháp hóa cơ chế hợp đồng sản xuất liên hợp&quot;">​</a></h2><p>Cơ chế hợp đồng sản xuất liên hợp là hệ thống cốt lõi phân phối nguồn lực của văn minh cộng sinh neo, và 《Luật Lao động Cộng sinh》 cố định nó dưới hình thức pháp luật:</p><ul><li><strong>Chủ thể hợp đồng</strong>: Mọi sự sống có khả năng lao động đều có thể là chủ thể hợp đồng, cả cá nhân và tập thể đều có thể ký hợp đồng.</li><li><strong>Nội dung hợp đồng</strong>: Bao gồm nhưng không giới hạn ở phát triển nguồn lực tu luyện, bảo trì位面, kế thừa tri thức, nghiên cứu và phát triển công nghệ, dịch vụ công cộng, v.v.</li><li><strong>Thời hạn hợp đồng</strong>: Quyết định theo bản chất nội dung hợp đồng, hợp đồng ngắn hạn là một đến ba năm, hợp đồng dài hạn là năm đến hai mươi năm, có thể gia hạn sau khi hết hạn.</li><li><strong>Phân phối lợi nhuận</strong>: Lợi nhuận của người ký hợp đồng gắn trực tiếp với sản lượng của họ, một phần sản lượng nộp cho tích lũy công cộng, phần còn lại thuộc về người ký hợp đồng.</li><li><strong>Cơ chế thoát</strong>: Người ký hợp đồng có quyền thoát khỏi hợp đồng sau khi thông báo trước trong thời hạn hợp lý, không bị buộc phải gắn bó trong mối quan hệ hợp đồng.</li><li><strong>Giải quyết tranh chấp</strong>: Tranh chấp hợp đồng được ưu tiên giải quyết thông qua trọng tài lao động, người không hài lòng với kết quả trọng tài có thể khởi kiện lên Tòa án Cộng sinh.</li></ul><h2 id="_4-bao-ve-lao-đong-đac-biet" tabindex="-1">4. Bảo vệ lao động đặc biệt <a class="header-anchor" href="#_4-bao-ve-lao-đong-đac-biet" aria-label="Permalink to &quot;4. Bảo vệ lao động đặc biệt&quot;">​</a></h2><p>Để đáp ứng nhu cầu đặc biệt của các hình thức sự sống khác nhau bên trong Hengyuanzhou, luật này thiết lập hệ thống bảo vệ lao động đặc biệt:</p><table tabindex="0"><thead><tr><th>Đối tượng bảo vệ</th><th>Biện pháp bảo vệ đặc biệt</th></tr></thead><tbody><tr><td>Người tu luyện sơ cấp</td><td>Không được giao việc làm có rủi ro cao vượt quá khả năng của họ, phải được trang bị hướng dẫn của cố vấn</td></tr><tr><td>Sự sống nữ trong thời kỳ mang thai và sinh đẻ</td><td>Có quyền nghỉ thai sản có lương không ít hơn sáu tháng, không được giao việc làm cường độ cao trong thời kỳ cho con bú</td></tr><tr><td>Sự sống khuyết tật và bị thương/ốm đau</td><td>Có quyền điều chỉnh vị trí lao động hợp lý và đảm bảo môi trường lao động không có rào cản</td></tr><tr><td>Người lao động từ tộc khác</td><td>Người sử dụng lao động phải tôn trọng đặc điểm sinh lý và thói quen văn hóa của tộc khác, cung cấp điều kiện lao động thích ứng</td></tr><tr><td>Người lao động cao tuổi</td><td>Sau khi đạt đến một độ tuổi nhất định, có thể xin giảm cường độ lao động hoặc chuyển sang vị trí cố vấn</td></tr></tbody></table><h2 id="_5-trach-nhiem-phap-ly-va-đam-bao-thuc-thi" tabindex="-1">5. Trách nhiệm pháp lý và đảm bảo thực thi <a class="header-anchor" href="#_5-trach-nhiem-phap-ly-va-đam-bao-thuc-thi" aria-label="Permalink to &quot;5. Trách nhiệm pháp lý và đảm bảo thực thi&quot;">​</a></h2><p>Người sử dụng lao động vi phạm quy định của luật này sẽ chịu trách nhiệm sau tùy theo mức độ nghiêm trọng của vi phạm:</p><ol><li>Thanh toán thù lao đúng hạn cho người lao động và tiền bồi thường (tiền bồi thường là một đến ba lần thù lao chưa thanh toán).</li><li>Bị ra lệnh khắc phục trong thời hạn, nếu không khắc phục trong thời hạn sẽ bị phạt tiền.</li><li>Trong trường hợp nghiêm trọng, thu hồi giấy phép kinh doanh và cấm các cá nhân có trách nhiệm liên quan从事 công việc quản lý trong một thời hạn nhất định.</li><li>Nếu cấu thành tội phạm, sẽ bị truy cứu trách nhiệm hình sự theo pháp luật.</li></ol><p>Nhà nước thành lập cơ quan thanh tra lao động, chịu trách nhiệm giám sát và kiểm tra việc tuân thủ luật lao động của người sử dụng lao động. Hội người lao động có quyền tham gia thanh tra lao động và đàm phán tập thể thay mặt cho người lao động.</p><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>《Luật Lao động Cộng sinh》 là载体 pháp luật của khái niệm &quot;nhiều lao động nhiều thu nhập&quot; của văn minh cộng sinh neo. Nó đã chuyển hóa lao động từ đối tượng bóc lột thành quyền được tôn trọng, và chuyển hóa phân phối từ chiếm đoạt kiểu cướp thành trả thù lao dựa trên đóng góp, đặt nền tảng hệ thống lao động vững chắc cho sự tiến bộ chung của mọi tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Nguyên tắc chung Hiến pháp Cộng sinh)</li><li>06-多劳多得分配原理 (Nguyên tắc phân phối nhiều lao động nhiều thu nhập)</li><li>22-资源分配联产承包机制 (Cơ chế hợp đồng sản xuất liên hợp phân phối nguồn lực)</li><li>42-消费者保护法 (Luật Bảo vệ Người tiêu dùng)</li></ul>',23)])])}const e=t(a,[["render",c]]);export{s as __pageData,e as default};
